+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewRealBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void contactFlowWorksInChromium() {
+        Page page = getPage();
+        assertEquals("Contact", page.locator("h1").innerText());
+
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.assertEnabled();
+
+        send.click();
+        name.assertErrorMessage("Name is required");
+        email.assertErrorMessage("Give an e-mail address or a phone number");
+        message.assertErrorMessage("Message is required");
+
+        name.setValue("Browser User");
+        email.setValue("browser@example.com");
+        message.setValue("Sent from Chromium");
+        page.keyboard().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        name.assertValue("");
+        email.assertValue("");
+        message.assertValue("");
+        send.assertDisabled();
+        GridElement.get(page).assertCellContent(0, 0, "Browser User");
+
+        name.setValue("Draft");
+        send.assertEnabled();
+        page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+        ButtonElement.getByText(dialog.getContentLocator(), "Keep editing").click();
+        name.assertValue("Draft");
+        assertEquals("contact", page.url().substring(page.url().lastIndexOf('/') + 1));
+
+        page.locator("vaadin-dialog[opened]").waitFor(
+                new com.microsoft.playwright.Locator.WaitForOptions()
+                        .setState(WaitForSelectorState.HIDDEN));
+        page.getByText("About", new Page.GetByTextOptions().setExact(true)).click();
+        page.locator("vaadin-dialog[opened]")
+                .getByText("Discard", new com.microsoft.playwright.Locator.GetByTextOptions()
+                        .setExact(true))
+                .click();
+        page.waitForURL("**/about");
+        assertEquals("About", page.locator("h1").innerText());
+    }
+}
