+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.annotation.DirtiesContext;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Autowired
+    private MessageStore messageStore;
+
+    @BeforeEach
+    void clearMessages() {
+        messageStore.clear();
+    }
+
+    @Test
+    void validatesSendsPersistsAndGuardsNavigation() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        Button send = find(Button.class).withText("Send").single();
+        assertTrue(send.isEnabled());
+
+        test(send).click();
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        assertInvalid(name, "Name is required");
+        assertInvalid(email, "Give an e-mail address or a phone number");
+        assertInvalid(message, "Message is required");
+        assertFalse(find(Notification.class).exists());
+
+        test(name).setValue("Ada");
+        test(email).setValue("not-an-address");
+        test(message).setValue("Hello");
+        test(send).click();
+        assertInvalid(email, "Enter a valid e-mail address");
+
+        test(email).setValue("ada@example.com");
+        fireShortcut(Key.ENTER);
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+        assertTrue(test(find(Notification.class).single()).getText()
+                .contains("Message sent"));
+        assertEquals("Ada", test(find(Grid.class).single()).getCellText(0, 0));
+
+        test(name).setValue("Grace");
+        test(phone).setValue("555-0100");
+        test(message).setValue("x".repeat(501));
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertInvalid(message, "Message must be at most 500 characters");
+        assertEquals(1, test(find(Grid.class).single()).size());
+        assertEquals("x".repeat(501), message.getValue());
+
+        test(message).setValue("Phone-only message");
+        test(send).click();
+        assertEquals("Grace", test(find(Grid.class).single()).getCellText(0, 0));
+        assertEquals("Ada", test(find(Grid.class).single()).getCellText(1, 0));
+        assertFalse(send.isEnabled());
+
+        test(name).setValue("Draft");
+        test(find(RouterLink.class).withText("About").single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        Dialog dialog = find(Dialog.class).single();
+        Button keepEditing = find(Button.class, dialog)
+                .withText("Keep editing").single();
+        test(keepEditing).click();
+        assertEquals("Draft", name.getValue());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test(find(RouterLink.class).withText("About").single()).click();
+        dialog = find(Dialog.class).single();
+        test(find(Button.class, dialog).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", find(H1.class).single().getText());
+
+        navigate(ContactView.class);
+        assertEquals("Grace", test(find(Grid.class).single()).getCellText(0, 0));
+        assertEquals("Ada", test(find(Grid.class).single()).getCellText(1, 0));
+    }
+
+    private static void assertInvalid(HasValidation field, String errorMessage) {
+        assertTrue(field.isInvalid());
+        assertEquals(errorMessage, field.getErrorMessage());
+    }
+}
